=== compare.js ===
// Compares dist-server with the baseline copy. Comments and require lines may differ; code may not.
// Usage: node compare.js <repo> <baseline> [-v]
const fs = require('fs')
const path = require('path')
const repo = process.argv[2]
const baseline = process.argv[3]
const verbose = process.argv.includes('-v')
const ts = require(path.join(repo, 'node_modules', 'typescript'))

function walk(dir, base, out) {
  for (const name of fs.readdirSync(dir)) {
    const full = path.join(dir, name)
    const st = fs.statSync(full)
    if (st.isDirectory()) walk(full, base, out)
    else if (name.endsWith('.js')) out.add(path.relative(base, full).replace(/\\/g, '/'))
  }
  return out
}

const printer = ts.createPrinter({ removeComments: true, newLine: ts.NewLineKind.LineFeed })

function hasRequireCall(node) {
  let found = false
  const visit = (n) => {
    if (found) return
    if (ts.isCallExpression(n) && ts.isIdentifier(n.expression) && n.expression.text === 'require') {
      found = true
      return
    }
    // do not look inside function bodies: a lazy require inside a function is code
    if (ts.isFunctionLike(n)) return
    ts.forEachChild(n, visit)
  }
  visit(node)
  return found
}

// Splits the top-level statements of a compiled file into require statements and code statements.
function split(file) {
  const text = fs.readFileSync(file, 'utf8')
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.ES2022, true, ts.ScriptKind.JS)
  const requires = []
  const code = []
  const requireNames = new Set()
  for (const stmt of sf.statements) {
    const printed = printer.printNode(ts.EmitHint.Unspecified, stmt, sf)
    if (ts.isVariableStatement(stmt)) {
      const decls = stmt.declarationList.declarations
      if (decls.every((d) => d.initializer && hasRequireCall(d.initializer))) {
        requires.push(printed)
        for (const d of decls) if (ts.isIdentifier(d.name)) requireNames.add(d.name.text)
        continue
      }
      // `const { a, b } = x` where x was bound by a require: the second half of a split destructured require
      if (decls.every((d) => ts.isObjectBindingPattern(d.name) && d.initializer && ts.isIdentifier(d.initializer) && requireNames.has(d.initializer.text))) {
        requires.push(printed)
        continue
      }
    }
    code.push(printed)
