// Scratch check (agent1): transpile one converted controller in memory and compare it, statement by statement and
// without comments, with the baseline compiled JavaScript. Writes only into the scratch folder given as argv[5].
// Usage: node cmp.js <repo> <baselineDir> <relative .ts path> <outDir>
const fs = require('fs')
const path = require('path')
const [repo, baseline, rel, outDir] = process.argv.slice(2)
const ts = require(path.join(repo, 'node_modules', 'typescript'))

const tsText = fs.readFileSync(path.join(repo, rel), 'utf8')
const out = ts.transpileModule(tsText, {
  fileName: rel,
  reportDiagnostics: true,
  compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.CommonJS, esModuleInterop: true, strict: true }
})
if (out.diagnostics && out.diagnostics.length) {
  for (const d of out.diagnostics) console.log('DIAG', ts.flattenDiagnosticMessageText(d.messageText, '\n'))
}
const outFile = path.join(outDir, path.basename(rel).replace(/\.ts$/, '.js'))
fs.writeFileSync(outFile, out.outputText)

const printer = ts.createPrinter({ removeComments: true, newLine: ts.NewLineKind.LineFeed })
function statements(text, name) {
  const sf = ts.createSourceFile(name, text, ts.ScriptTarget.ES2022, true, ts.ScriptKind.JS)
  return sf.statements.map((s) => printer.printNode(ts.EmitHint.Unspecified, s, sf))
}
const baseText = fs.readFileSync(path.join(baseline, rel.replace(/\.ts$/, '.js')), 'utf8')
const a = statements(baseText, 'base.js')
const b = statements(out.outputText, 'new.js')

// Line-level diff of the comment-free print of both files
const al = a.join('\n').split('\n')
const bl = b.join('\n').split('\n')
const setA = new Map()
for (const l of al) setA.set(l, (setA.get(l) || 0) + 1)
const setB = new Map()
for (const l of bl) setB.set(l, (setB.get(l) || 0) + 1)
console.log(`baseline: ${a.length} statements, ${al.length} lines; new: ${b.length} statements, ${bl.length} lines`)
console.log('--- lines only in baseline ---')
for (const [l, n] of setA) if ((setB.get(l) || 0) < n) console.log('  - ' + l)
console.log('--- lines only in new ---')
for (const [l, n] of setB) if ((setA.get(l) || 0) < n) console.log('  + ' + l)

// Comments: count the comments in each compiled file (JSDoc blocks must survive)
function comments(text) {
  const m = text.match(/\/\*\*[\s\S]*?\*\/|\/\/[^\n]*/g) || []
  return m
}
const ca = comments(baseText)
const cb = comments(out.outputText)
console.log(`comments: baseline ${ca.length}, new ${cb.length}`)
const cset = new Set(cb.map((c) => c.replace(/\s+/g, ' ')))
for (const c of ca) if (!cset.has(c.replace(/\s+/g, ' '))) console.log('  comment missing in new: ' + c.replace(/\s+/g, ' ').slice(0, 160))
const aset = new Set(ca.map((c) => c.replace(/\s+/g, ' ')))
for (const c of cb) if (!aset.has(c.replace(/\s+/g, ' '))) console.log('  comment only in new: ' + c.replace(/\s+/g, ' ').slice(0, 200))

