}
const outFile = path.join(outDir, path.basename(rel).replace(/\.ts$/, '.js'))
fs.writeFileSync(outFile, out.outputText)

const printer = ts.createPrinter({ removeComments: true, newLine: ts.NewLineKind.LineFeed })
function statements(text, name) {
  const sf = ts.createSourceFile(name, text, ts.ScriptTarget.ES2022, true, ts.ScriptKind.JS)
  return sf.statements.map((s) => printer.printNode(ts.EmitHint.Unspecified, s, sf))
}
