const bl = b.join('\n').split('\n')
const setA = new Map()
for (const l of al) setA.set(l, (setA.get(l) || 0) + 1)
const setB = new Map()
for (const l of bl) setB.set(l, (setB.get(l) || 0) + 1)
console.log(`baseline: ${a.length} statements, ${al.length} lines; new: ${b.length} statements, ${bl.length} lines`)
console.log('--- lines only in baseline ---')
for (const [l, n] of setA) if ((setB.get(l) || 0) < n) console.log('  - ' + l)
console.log('--- lines only in new ---')
for (const [l, n] of setB) if ((setA.get(l) || 0) < n) console.log('  + ' + l)

// Comments: count the comments in each compiled file (JSDoc blocks must survive)
function comments(text) {
  const m = text.match(/\/\*\*[\s\S]*?\*\/|\/\/[^\n]*/g) || []
  return m
}
const ca = comments(baseText)
const cb = comments(out.outputText)
console.log(`comments: baseline ${ca.length}, new ${cb.length}`)
const cset = new Set(cb.map((c) => c.replace(/\s+/g, ' ')))
for (const c of ca) if (!cset.has(c.replace(/\s+/g, ' '))) console.log('  comment missing in new: ' + c.replace(/\s+/g, ' ').slice(0, 160))
const aset = new Set(ca.map((c) => c.replace(/\s+/g, ' ')))
for (const c of cb) if (!aset.has(c.replace(/\s+/g, ' '))) console.log('  comment only in new: ' + c.replace(/\s+/g, ' ').slice(0, 200))

